// In-memory Firestore transport for testing real client transactions, not a rules emulator.
export function createMemoryFirestore(now=()=>Date.now()){
 const records=new Map(),listeners=new Set();let serial=0;
 const copy=x=>x&&typeof x.toMillis==='function'?{toMillis:()=>x.toMillis()}:Array.isArray(x)?x.map(copy):x&&typeof x==='object'?Object.fromEntries(Object.entries(x).map(([k,v])=>[k,copy(v)])):x;
 const timestamp=()=>{const t=now();return {toMillis:()=>t};};
 const resolve=x=>x?.__stamp?timestamp():Array.isArray(x)?x.map(resolve):x&&typeof x==='object'&&typeof x.toMillis!=='function'?Object.fromEntries(Object.entries(x).map(([k,v])=>[k,resolve(v)])):copy(x);
 const snap=ref=>{const record=records.get(ref.path);return {id:ref.id,exists:()=>!!record,data:()=>copy(record?.data)};};
 const docs=q=>{let data=[...records].filter(([path])=>path.startsWith(q.path+'/')&&!path.slice(q.path.length+1).includes('/')).map(([path,r])=>({path,data:r.data}));for(const c of q.constraints??[])if(c.kind==='where')data=data.filter(r=>r.data[c.field]===c.value);for(const c of q.constraints??[])if(c.kind==='order')data.sort((a,b)=>{const av=a.data[c.field]?.toMillis?.()??a.data[c.field],bv=b.data[c.field]?.toMillis?.()??b.data[c.field];return (av<bv?-1:av>bv?1:0)*(c.order==='desc'?-1:1);});const limit=q.constraints?.find(c=>c.kind==='limit')?.value??Infinity;return {docs:data.slice(0,limit).map(d=>snap({path:d.path,id:d.path.split('/').at(-1)}))};};
 const sdk={doc:(db,...segments)=>{let path;if(db?.path)path=db.path+'/'+(segments.join('/')||'id-'+(++serial));else path=segments.join('/');return {path,id:path.split('/').at(-1)};},collection:(db,path)=>({path}),serverTimestamp:()=>({__stamp:true}),where:(field,op,value)=>({kind:'where',field,value}),orderBy:(field,order)=>({kind:'order',field,order}),limit:value=>({kind:'limit',value}),query:(col,...constraints)=>({...col,constraints}),getDoc:async ref=>snap(ref),getDocFromServer:async ref=>snap(ref),getDocs:async q=>docs(q),onSnapshot:(q,fn)=>{const l={q,fn};listeners.add(l);queueMicrotask(()=>fn(docs(q)));return ()=>listeners.delete(l);},runTransaction:async(db,fn)=>{for(let attempt=0;attempt<6;attempt++){const reads=new Map(),writes=[];const tx={get:async ref=>{if(writes.length)throw Error('reads-must-precede-writes');reads.set(ref.path,records.get(ref.path)?.version??0);return snap(ref);},set:(ref,data)=>writes.push({ref,data,update:false}),update:(ref,data)=>writes.push({ref,data,update:true})};const result=await fn(tx);if([...reads].some(([p,v])=>(records.get(p)?.version??0)!==v))continue;for(const w of writes){const old=records.get(w.ref.path);if(w.update&&!old)throw Error('not-found');records.set(w.ref.path,{data:resolve(w.update?{...old.data,...w.data}:w.data),version:(old?.version??0)+1});}for(const l of listeners)queueMicrotask(()=>l.fn(docs(l.q)));return result;}throw Error('transaction-conflict');}};
 return {sdk,db:{},records};
}
